/** ANPR ngã tư Vinh · Nghệ An — mock P1 (`gis-camera-map`). */

export type VehicleKind = 'xe con' | 'xe tải' | 'xe khách' | 'xe máy';

export type SpeedEvent = {
  id: string;
  at: string;
  plate: string;
  vehicleType: VehicleKind;
  speedKmh: number;
  limitKmh: number;
};

export type CountByType = Record<VehicleKind, number>;

export type AnprCameraSeed = {
  id: string;
  code: string;
  name: string;
  intersection: string;
  route: string;
  km: string;
  lat: number;
  lng: number;
  online: boolean;
  model: string;
  host: string;
  httpPort: number;
  speedLimitKmh: number;
  countByType: CountByType;
  countToday: number;
  events: SpeedEvent[];
};

export type WallMode = 'p22' | 'p32' | 'p1' | 'free';
export type MapSplit = 'split50' | 'off';
export type InspectTab = 'info' | 'count' | 'speed';

export const WALL_LAYOUT_OPTIONS: ReadonlyArray<{ value: WallMode; label: string }> = [
  { value: 'p22', label: 'Lưới 2×2' },
  { value: 'p32', label: 'Lưới 3×2' },
  { value: 'p1', label: '1 cam lớn' },
  { value: 'free', label: 'Thêm tự do' },
];

export const MAP_SPLIT_OPTIONS: ReadonlyArray<{ value: MapSplit; label: string }> = [
  { value: 'split50', label: 'Bản đồ 50/50' },
  { value: 'off', label: 'Ẩn bản đồ' },
];

