export const LAYOUT_STORAGE_KEY = 'rmms:gis-camera-map:layout';

const MODEL = 'iDS-TCM403-GIR';

function sumCount(c: CountByType): number {
  return c['xe con'] + c['xe tải'] + c['xe khách'] + c['xe máy'];
}

function ev(
  id: string,
  at: string,
  plate: string,
  vehicleType: VehicleKind,
  speedKmh: number,
  limitKmh: number,
): SpeedEvent {
  return { id, at, plate, vehicleType, speedKmh, limitKmh };
}

function cam(
  n: number,
  intersection: string,
  lat: number,
  lng: number,
  km: string,
  route: string,
  count: CountByType,
  events: SpeedEvent[],
  extra?: Partial<AnprCameraSeed>,
): AnprCameraSeed {
  const code = `CAM-VINH-${String(n).padStart(2, '0')}`;
  return {
    id: code,
    code,
    name: `ANPR ${intersection}`,
    intersection,
    route,
    km,
    lat,
    lng,
    online: extra?.online ?? true,
    model: MODEL,
    host: extra?.host ?? `10.20.1.${30 + n}`,
    httpPort: 80,
    speedLimitKmh: extra?.speedLimitKmh ?? 50,
    countByType: count,
    countToday: sumCount(count),
    events,
    ...extra,
  };
}

