const VEHICLE_CYCLE: VehicleKind[] = ['xe con', 'xe máy', 'xe con', 'xe tải', 'xe khách', 'xe máy'];
const PLATE_TAIL = [18, 44, 71, 92, 5, 33, 60, 87, 11, 26];

export function cloneCameras(src: AnprCameraSeed[] = VINH_ANPR_CAMERAS): AnprCameraSeed[] {
  return src.map((c) => ({
    ...c,
    countByType: { ...c.countByType },
    events: c.events.map((e) => ({ ...e })),
  }));
}

export function slotCountOf(mode: WallMode, slotLen: number): number {
  if (mode === 'free') return Math.max(slotLen, 1);
  if (mode === 'p1') return 1;
  if (mode === 'p32') return 6;
  return 4;
}

export function tickLiveTraffic(cameras: AnprCameraSeed[], tick: number): AnprCameraSeed[] {
  const kinds = VEHICLE_CYCLE;
  return cameras.map((c, i) => {
    if (!c.online) return c;
    const kind = kinds[(tick + i) % kinds.length];
    const add = 1 + ((tick + i) % 3 === 0 ? 1 : 0);
    const countByType = { ...c.countByType, [kind]: c.countByType[kind] + add };
    const countToday = sumCount(countByType);
    const events = [...c.events];
    if ((tick + i) % 11 === 0) {
      const limit = c.speedLimitKmh;
      const over = 12 + ((tick + i) % 18);
      const hh = String(7 + (tick % 12)).padStart(2, '0');
      const mm = String((tick * 3) % 60).padStart(2, '0');
      events.unshift(
        ev(
          `live-${c.id}-${tick}`,
          `${hh}:${mm}`,
          `37A-${String(100 + PLATE_TAIL[i] + (tick % 9)).padStart(3, '0')}.${String(10 + (tick % 89)).padStart(2, '0')}`,
          kind,
          limit + over,
          limit,
        ),
      );
      if (events.length > 24) events.length = 24;
    }
    return { ...c, countByType, countToday, events };
  });
}

export function kpiOf(cameras: AnprCameraSeed[]): {
  online: number;
  total: number;
  vehicles: number;
  speeding: number;
  offline: number;
} {
  const online = cameras.filter((c) => c.online).length;
  return {
    online,
    total: cameras.length,
    vehicles: cameras.reduce((s, c) => s + c.countToday, 0),
    speeding: cameras.reduce((s, c) => s + c.events.length, 0),
    offline: cameras.length - online,
  };
}

export type PersistedLayout = {
  mode: WallMode;
  mapSplit: MapSplit;
  mapWPct: number | null;
  slots: Array<string | null>;
};

export function loadLayout(): PersistedLayout {
  const fallback: PersistedLayout = {
    mode: 'p22',
    mapSplit: 'split50',
    mapWPct: 50,
    slots: VINH_ANPR_CAMERAS.slice(0, 4).map((c) => c.id),
  };
  try {
    const raw = JSON.parse(localStorage.getItem(LAYOUT_STORAGE_KEY) || '{}') as Partial<PersistedLayout>;
    const mode = WALL_LAYOUT_OPTIONS.some((o) => o.value === raw.mode) ? (raw.mode as WallMode) : fallback.mode;
    const mapSplit = MAP_SPLIT_OPTIONS.some((o) => o.value === raw.mapSplit)
      ? (raw.mapSplit as MapSplit)
      : fallback.mapSplit;
    const mapWPct = typeof raw.mapWPct === 'number' ? raw.mapWPct : fallback.mapWPct;
    let slots = Array.isArray(raw.slots) ? raw.slots : fallback.slots;
    const n = slotCountOf(mode, slots.length);
    if (mode !== 'free') {
      while (slots.length < n) slots = [...slots, null];
      slots = slots.slice(0, n);
    } else if (!slots.length) {
      slots = [null, null];
    }
    return { mode, mapSplit, mapWPct, slots };
  } catch {
    return fallback;
  }
}

export function saveLayout(layout: PersistedLayout): void {
  localStorage.setItem(LAYOUT_STORAGE_KEY, JSON.stringify(layout));
}
