import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Select } from '@linm-soft-org/linm-web-common-components';
import { resetLeafletContainer, useLeaflet } from '../../demo/useLeaflet';
import {
  MapViewToggleIcon,
  applyClipBasemapStyle,
  attachVnClipBasemap,
  bindAssetPopup,
  buildMapPopupHtml,
  CLIP_STYLE_OPTIONS,
  createAssetLeafletIcon,
  ensureAssetIconStyles,
  VN_CLIP_MIN_ZOOM,
  vnLeafletMapOptions,
  type ClipStyleKind,
} from '../../shared/map';
import {
  MY_LOCATION_LABEL,
  MY_LOCATION_TITLE,
  locateUserOnMap,
  type MyLocationHold,
} from '../../shared/map/locateUserOnMap';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import { ensureGisMapPageFill } from '../../shared/map/gisMapPageFill';
import live from '../GisDrawLivePage/GisDrawLivePage.module.css';
import styles from './GisCameraMapPage.module.css';
import '../../shared/map/gisMapStack.css';
import {
  INSPECT_TABS,
  MAP_SPLIT_OPTIONS,
  VINH_CAMERA_FIT,
  WALL_LAYOUT_OPTIONS,
  cloneCameras,
  kpiOf,
  loadLayout,
  saveLayout,
  slotCountOf,
  tickLiveTraffic,
  type AnprCameraSeed,
  type InspectTab,
  type MapSplit,
  type WallMode,
} from './vinhAnprCameraSeed';

function fmtNum(n: number): string {
  return n.toLocaleString('vi-VN');
}

function popupFor(c: AnprCameraSeed): string {
  return buildMapPopupHtml({
    name: c.intersection,
    code: c.code,
    km: c.km,
    route: c.route,
    lat: c.lat,
    lng: c.lng,
    assetCode: 'CAM',
    extraRows: [
      { label: 'Tổng số phương tiện:', value: fmtNum(c.countToday) },
      { label: 'Tổng số xe vượt tốc độ:', value: fmtNum(c.events.length) },
    ],
    action: { label: 'Xem chi tiết', dataCamDetail: c.id },
  });
}

const GisCameraMapPage: React.FC = () => {
  useShellPageTitle('Bản đồ camera');
  const { ready, error: leafletError } = useLeaflet();
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const clipLayerRef = useRef<L.Layer | null>(null);
  const pinLayerRef = useRef<L.FeatureGroup | null>(null);
  const markersRef = useRef<Record<string, L.Marker>>({});
  const myLocationHoldRef = useRef<MyLocationHold>({ group: null });
  const dragRef = useRef<{ id: string; fromPool: boolean } | null>(null);
  const camerasRef = useRef<AnprCameraSeed[]>([]);
  const selectCamRef = useRef<(id: string, tab?: InspectTab) => void>(() => undefined);

  const [viewFull, setViewFull] = useState(false);
  const [clipStyle, setClipStyle] = useState<ClipStyleKind>('default');
  const [locating, setLocating] = useState(false);
  const [overlayStatus, setOverlayStatus] = useState('Seed ANPR Vinh · Nghệ An');
  const [cameras, setCameras] = useState<AnprCameraSeed[]>(() => cloneCameras());
  const [mode, setMode] = useState<WallMode>('p22');
  const [mapSplit, setMapSplit] = useState<MapSplit>('split50');
  const [mapWPct, setMapWPct] = useState<number | null>(50);
  const mapWPctRef = useRef<number | null>(50);
  const [slots, setSlots] = useState<Array<string | null>>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [inspectTab, setInspectTab] = useState<InspectTab>('info');
  const [inspectOpen, setInspectOpen] = useState(false);
  const [fsId, setFsId] = useState<string | null>(null);
  const [mapEpoch, setMapEpoch] = useState(0);
  const [splitDrag, setSplitDrag] = useState(false);

  camerasRef.current = cameras;
  mapWPctRef.current = mapWPct;

  const kpi = useMemo(() => kpiOf(cameras), [cameras]);
  const selected = cameras.find((c) => c.id === selectedId) ?? null;
  const fsCam = cameras.find((c) => c.id === fsId) ?? null;
  const used = useMemo(() => new Set(slots.filter(Boolean) as string[]), [slots]);
  const nSlots = slotCountOf(mode, slots.length);

  const persist = useCallback(
    (next: { mode?: WallMode; mapSplit?: MapSplit; mapWPct?: number | null; slots?: Array<string | null> }) => {
      const layout = {
        mode: next.mode ?? mode,
        mapSplit: next.mapSplit ?? mapSplit,
        mapWPct: next.mapWPct !== undefined ? next.mapWPct : mapWPct,
        slots: next.slots ?? slots,
      };
      saveLayout(layout);
    },
    [mode, mapSplit, mapWPct, slots],
  );

  const selectCam = useCallback((id: string, tab: InspectTab = 'info') => {
    setSelectedId(id);
    setInspectTab(tab);
    setInspectOpen(true);
    const leaflet = mapInstanceRef.current as (L.Map & { closePopup?: () => void }) | null;
    leaflet?.closePopup?.();
  }, []);
  selectCamRef.current = selectCam;

  const locateMe = useCallback(() => {
    const map = mapInstanceRef.current;
    const Lf = window.L;
    if (!map || !Lf) return;
    setLocating(true);
    void locateUserOnMap(map, Lf, myLocationHoldRef.current)
      .catch((err: unknown) => {
        setOverlayStatus(err instanceof Error ? err.message : 'Không lấy được vị trí');
      })
      .finally(() => setLocating(false));
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => ensureGisMapPageFill(), 0);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => {
      const saved = loadLayout();
      setMode(saved.mode);
      setMapSplit(saved.mapSplit);
      setMapWPct(saved.mapWPct);
      setSlots(saved.slots);
    }, 0);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    const t = window.setTimeout(() => {
      const host = document.querySelector('[data-gis-map-page]');
      if (host) window.dispatchEvent(new Event('resize'));
      mapInstanceRef.current?.invalidateSize?.();
    }, 0);
    return () => window.clearTimeout(t);
  }, [viewFull, mapSplit, mapWPct, mode]);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setCameras((prev) => tickLiveTraffic(prev, Date.now()));
    }, 3000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!ready || !mapRef.current) return undefined;
    const L = window.L;
    if (!L?.map) return undefined;
    const el = mapRef.current;
    let map: L.Map | null = null;
    let onPopupAction: ((ev: Event) => void) | null = null;
    const timer = window.setTimeout(() => {
      if (mapInstanceRef.current) {
        try {
          mapInstanceRef.current.remove();
        } catch {
          /* HMR */
        }
        mapInstanceRef.current = null;
      }
      resetLeafletContainer(el);
      try {
        map = L.map(el, vnLeafletMapOptions({ center: [18.6796, 105.6813], zoom: 13 }));
      } catch {
        resetLeafletContainer(el);
        map = L.map(el, vnLeafletMapOptions({ center: [18.6796, 105.6813], zoom: 13 }));
      }
      try {
        clipLayerRef.current = attachVnClipBasemap(map, clipStyle);
      } catch (clipErr) {
        setOverlayStatus(clipErr instanceof Error ? clipErr.message : 'Không gắn nền clip BFF');
        return;
      }
      pinLayerRef.current = new L.FeatureGroup().addTo(map);
      mapInstanceRef.current = map;
      map.fitBounds(VINH_CAMERA_FIT, { padding: [28, 28], maxZoom: 15 });
      map.setMinZoom?.(VN_CLIP_MIN_ZOOM);
      onPopupAction = (ev: Event) => {
        const hit = (ev.target as HTMLElement | null)?.closest?.('[data-cam-detail]');
        if (!hit) return;
        ev.preventDefault();
        ev.stopPropagation();
        const id = hit.getAttribute('data-cam-detail');
        if (id) selectCamRef.current?.(id, 'info');
      };
      const host = map.getContainer?.();
      if (host && onPopupAction) host.addEventListener('click', onPopupAction, true);
      setMapEpoch((n) => n + 1);
      setOverlayStatus('Clip BFF · 10 camera ANPR Vinh');
    }, 0);

    return () => {
      window.clearTimeout(timer);
      try {
        const host = map?.getContainer?.();
        if (onPopupAction && host) {
          host.removeEventListener('click', onPopupAction, true);
        }
        map?.remove();
      } catch {
        /* gone */
      }
      mapInstanceRef.current = null;
      clipLayerRef.current = null;
      pinLayerRef.current = null;
      markersRef.current = {};
      myLocationHoldRef.current.group = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- init once when Leaflet ready
  }, [ready]);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const L = window.L;
    const layer = pinLayerRef.current;
    if (!map || !L || !layer) return undefined;
    const timer = window.setTimeout(() => {
      ensureAssetIconStyles();
      layer.clearLayers();
      markersRef.current = {};
      camerasRef.current.forEach((c) => {
        const icon = createAssetLeafletIcon(L, 'CAM', c.online ? 'ok' : 'broken');
        const marker = L.marker([c.lat, c.lng], icon ? { icon, keyboard: false } : { keyboard: false });
        bindAssetPopup(marker, popupFor(c), L);
        layer.addLayer(marker);
        markersRef.current[c.id] = marker;
      });
    }, 0);
    return () => window.clearTimeout(timer);
  }, [mapEpoch]);

  useEffect(() => {
    const L = window.L;
    if (!L) return;
    cameras.forEach((c) => {
      const m = markersRef.current[c.id];
      if (m) bindAssetPopup(m, popupFor(c), L);
    });
  }, [cameras]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      setFsId(null);
      setInspectOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const applySlots = useCallback(
    (nextSlots: Array<string | null>, nextMode = mode) => {
      let slotsNext = nextSlots;
      const n = slotCountOf(nextMode, slotsNext.length);
      if (nextMode !== 'free') {
        while (slotsNext.length < n) slotsNext = [...slotsNext, null];
        slotsNext = slotsNext.slice(0, n);
      } else if (!slotsNext.length) {
        slotsNext = [null, null];
      }
      setSlots(slotsNext);
      persist({ slots: slotsNext, mode: nextMode });
    },
    [mode, persist],
  );

  const onWallMode = (value: string) => {
    const next = value as WallMode;
    setMode(next);
    applySlots(slots, next);
    setOverlayStatus(next === 'free' ? 'Mode thêm tự do — kéo từ pool' : 'Mode lưới cố định');
  };

  const onMapSplit = (value: string) => {
    const next = value as MapSplit;
    setMapSplit(next);
    persist({ mapSplit: next, mapWPct: next === 'off' ? mapWPct : mapWPct ?? 50 });
    setOverlayStatus(next === 'off' ? 'Đã ẩn bản đồ' : 'Bản đồ 50/50');
  };

  const compactFree = (list: Array<string | null>) => {
    if (mode !== 'free') return list;
    const filled = list.filter(Boolean);
    const empties = list.filter((s) => !s);
    let next = [...filled, ...empties];
    while (next.length < 2) next.push(null);
    return next;
  };

  const dropOnSlot = (to: number) => {
    const drag = dragRef.current;
    if (!drag) return;
    const from = slots.indexOf(drag.id);
    if (from === to) return;
    if (drag.fromPool && slots.includes(drag.id)) return;
    const next = [...slots];
    while (next.length <= to) next.push(null);
    const prev = next[to];
    next[to] = drag.id;
    if (from >= 0) next[from] = prev || null;
    applySlots(compactFree(next));
    setOverlayStatus(drag.fromPool ? 'Đã thêm từ pool' : 'Đã sắp xếp wall');
    dragRef.current = null;
  };

  const addFromPool = (id: string) => {
    if (slots.includes(id)) return;
    let next = [...slots];
    const to = next.indexOf(null);
    if (to < 0) {
      if (mode !== 'free') {
        setOverlayStatus('Hết ô — đổi Thêm tự do hoặc lưới lớn hơn');
        return;
      }
      next.push(id);
    } else {
      next[to] = id;
    }
    applySlots(next);
    setOverlayStatus('Đã thêm từ pool');
  };

  const removeFromWall = (id: string) => {
    const from = slots.indexOf(id);
    if (from < 0) return;
    const next = [...slots];
    next[from] = null;
    applySlots(compactFree(next));
    setOverlayStatus('Đã gỡ khỏi wall');
  };

  const onSplitterDown = (e: React.MouseEvent) => {
    if (mapSplit === 'off') return;
    e.preventDefault();
    setSplitDrag(true);
    const startX = e.clientX;
    const workspace = (e.currentTarget.parentElement as HTMLElement | null)?.getBoundingClientRect();
    const startPct = mapWPct ?? 50;
    const onMove = (ev: MouseEvent) => {
      if (!workspace) return;
      const dx = ev.clientX - startX;
      const pct = Math.min(72, Math.max(28, startPct - (dx / workspace.width) * 100));
      mapWPctRef.current = pct;
      setMapWPct(pct);
    };
    const onUp = () => {
      setSplitDrag(false);
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      persist({ mapWPct: mapWPctRef.current ?? startPct });
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  const camById = (id: string | null) => cameras.find((c) => c.id === id);

  const workspaceClass =
    `${styles.workspace} ${mapSplit === 'off' ? styles.mapOff : ''}`.trim();
  const workspaceStyle: React.CSSProperties | undefined = viewFull
    ? { gridTemplateColumns: '1fr' }
    : mapSplit === 'split50' && mapWPct != null
      ? { gridTemplateColumns: `200px minmax(0,1fr) 6px minmax(180px, ${mapWPct}%)` }
      : undefined;

  return (
    <div
      className={`${live.page} ${viewFull ? live.full : live.dock}`}
      data-testid="rmms-gis-camera-map-page"
      data-gis-map-page
    >
      <div className={`${styles.toolbar} ${live.dockOnly}`}>
        <div className={styles.kpis}>
          <div className={styles.kpi}>
            <div className={styles.kpiLbl}>Camera online</div>
            <div className={styles.kpiVal}>
              {kpi.online}/{kpi.total}
            </div>
          </div>
          <div className={styles.kpi}>
            <div className={styles.kpiLbl}>Tổng số phương tiện</div>
            <div className={styles.kpiVal}>{fmtNum(kpi.vehicles)}</div>
          </div>
          <div className={styles.kpi}>
            <div className={styles.kpiLbl}>Tổng số xe vượt tốc độ</div>
            <div className={styles.kpiVal}>{fmtNum(kpi.speeding)}</div>
          </div>
          <div className={styles.kpi}>
            <div className={styles.kpiLbl}>Mất tín hiệu</div>
            <div className={styles.kpiVal}>{kpi.offline}</div>
          </div>
        </div>
        <div className={styles.selects}>
          <Select
            label="Bố cục"
            options={WALL_LAYOUT_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
            value={mode}
            onChange={(e) => onWallMode(String(e.target.value))}
            size="small"
            data-testid="rmms-gis-camera-layout"
          />
          <Select
            label="Bản đồ"
            options={MAP_SPLIT_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
            value={mapSplit}
            onChange={(e) => onMapSplit(String(e.target.value))}
            size="small"
            data-testid="rmms-gis-camera-map-split"
          />
        </div>
      </div>
      <div className={`${styles.status} ${live.dockOnly}`}>{overlayStatus} · kéo pool vào wall · kéo mép map để đổi 50/50</div>

      <div className={workspaceClass} style={workspaceStyle} data-gis-map-app>
        {!viewFull && (
        <section className={styles.panel}>
          <h2>
            Pool camera <span className={styles.meta}>kéo vào wall</span>
          </h2>
          <div className={styles.pool}>
            {cameras.map((c) => {
              const inWall = used.has(c.id);
              return (
                <div
                  key={c.id}
                  className={`${styles.poolItem} ${inWall ? styles.used : ''}`}
                  draggable={!inWall}
                  onDragStart={() => {
                    dragRef.current = { id: c.id, fromPool: true };
                  }}
                  onDragEnd={() => {
                    dragRef.current = null;
                  }}
                  onClick={() => {
                    if (!inWall) addFromPool(c.id);
                  }}
                >
                  <div className={styles.poolId}>{c.code}</div>
                  <div className={styles.meta}>{c.intersection}</div>
                  <span className={`${styles.st} ${c.online ? styles.stOk : styles.stOff}`}>
                    {c.online ? 'Online' : 'Offline'}
                  </span>
                </div>
              );
            })}
            <div
              className={styles.poolDrop}
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                const drag = dragRef.current;
                if (!drag || drag.fromPool) return;
                removeFromWall(drag.id);
                dragRef.current = null;
              }}
            >
              Kéo tile wall về đây để gỡ
            </div>
          </div>
        </section>
        )}

        {!viewFull && (
        <section className={styles.panel}>
          <h2>
            Wall nhiều camera <span className={styles.meta}>kéo-thả · persist</span>
          </h2>
          <div className={`${styles.wall} ${styles[mode === 'free' ? 'p22' : mode]}`}>
            {Array.from({ length: nSlots }, (_, i) => {
              const id = slots[i];
              const c = id ? camById(id) : null;
              if (!c) {
                return (
                  <div
                    key={`empty-${i}`}
                    className={`${styles.tile} ${styles.empty}`}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => {
                      e.preventDefault();
                      dropOnSlot(i);
                    }}
                  >
                    Kéo camera từ pool vào ô
                  </div>
                );
              }
              return (
                <div
                  key={c.id}
                  className={`${styles.tile} ${c.online ? '' : styles.off} ${selectedId === c.id ? styles.sel : ''}`}
                  draggable
                  onDragStart={() => {
                    dragRef.current = { id: c.id, fromPool: false };
                  }}
                  onDragEnd={() => {
                    dragRef.current = null;
                  }}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.preventDefault();
                    dropOnSlot(i);
                  }}
                >
                  <div className={styles.hud}>
                    <span>{c.code}</span>
                    <span className={`${styles.st} ${c.online ? styles.stOk : styles.stOff}`}>
                      {c.online ? 'Online' : 'Offline'}
                    </span>
                  </div>
                  <div className={styles.live}>
                    {c.online ? '● LIVE mock' : 'Mất tín hiệu'}
                    <br />
                    <span className={styles.meta}>{c.intersection}</span>
                    <br />
                    {fmtNum(c.countToday)} xe · {c.events.length} vượt tốc
                  </div>
                  <div className={styles.foot}>
                    <button type="button" onClick={() => selectCam(c.id, 'count')}>
                      Xem live
                    </button>
                    <button type="button" onClick={() => setFsId(c.id)}>
                      Toàn màn hình
                    </button>
                    <button type="button" onClick={() => removeFromWall(c.id)}>
                      Gỡ
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
        )}

        {!viewFull && (
        <div
          className={`${styles.splitter} ${splitDrag ? styles.on : ''}`}
          role="separator"
          aria-orientation="vertical"
          title="Kéo để đổi kích thước bản đồ"
          onMouseDown={onSplitterDown}
        />
        )}

        <main className={styles.mapCol} data-gis-map-main>
          <div className={live.mapShell}>
            <div className={live.mapHost}>
              {!ready && !leafletError && <div className={live.mapLoading}>Đang tải Leaflet…</div>}
              {leafletError && <div className={live.mapError}>{leafletError}</div>}
              <div
                ref={mapRef}
                className={live.mapEl}
                role="application"
                aria-label="Bản đồ camera"
              />
            </div>
            <div className={live.mapBar} role="toolbar" aria-label="Lớp nền bản đồ">
              <div className={live.mapBasemaps} role="group" aria-label="Basemap">
                {CLIP_STYLE_OPTIONS.map((opt) => (
                  <button
                    key={opt.id}
                    type="button"
                    className={clipStyle === opt.id ? live.isActive : undefined}
                    data-basemap={opt.id}
                    title={opt.title}
                    aria-label={opt.title}
                    aria-pressed={clipStyle === opt.id}
                    onClick={() => {
                      setClipStyle(opt.id);
                      if (clipLayerRef.current) {
                        applyClipBasemapStyle(clipLayerRef.current, opt.id);
                      }
                    }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <button
                type="button"
                className={live.fitBtn}
                data-action="locate-me"
                title={MY_LOCATION_TITLE}
                aria-label={MY_LOCATION_TITLE}
                aria-busy={locating}
                disabled={locating}
                onClick={locateMe}
              >
                {MY_LOCATION_LABEL}
              </button>
              <button
                type="button"
                className={live.btnMapView}
                data-action="map-view-toggle"
                title={viewFull ? 'Thu về dock (mini)' : 'Phóng full map'}
                aria-label={viewFull ? 'Thu về dock' : 'Phóng full map'}
                aria-pressed={viewFull}
                onClick={() => setViewFull((v) => !v)}
              >
                <MapViewToggleIcon expanded={viewFull} className={live.mapViewIco} />
              </button>
            </div>
          </div>
        </main>
      </div>

      {inspectOpen && selected && (
        <>
          <div
            className={styles.overlay}
            onClick={() => setInspectOpen(false)}
            role="presentation"
          />
          <aside className={styles.slide} aria-label="Chi tiết camera">
            <div className={styles.slideHead}>
              <h3>
                {selected.code} · {selected.intersection}
              </h3>
              <button type="button" className={live.btn} onClick={() => setFsId(selected.id)}>
                Toàn màn hình
              </button>
              <button type="button" className={live.btn} onClick={() => setInspectOpen(false)}>
                Đóng
              </button>
            </div>
            <div className={styles.tabs} role="tablist">
              {INSPECT_TABS.map((t) => (
                <button
                  key={t.id}
                  type="button"
                  role="tab"
                  aria-selected={inspectTab === t.id}
                  className={inspectTab === t.id ? styles.tabOn : undefined}
                  onClick={() => setInspectTab(t.id)}
                >
                  {t.label}
                </button>
              ))}
            </div>
            <div className={styles.slideBody}>
              {inspectTab === 'info' && (
                <>
                  <div className={styles.row}>
                    <span>Tên</span>
                    <strong>{selected.name}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>Mã TS</span>
                    <strong>{selected.code}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>Model</span>
                    <strong>{selected.model}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>Ngã tư</span>
                    <strong>{selected.intersection}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>Tuyến</span>
                    <strong>{selected.route}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>KM</span>
                    <strong>{selected.km}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>GPS</span>
                    <strong>
                      {selected.lat.toFixed(5)}, {selected.lng.toFixed(5)}
                    </strong>
                  </div>
                  <div className={styles.row}>
                    <span>IP / HTTP</span>
                    <strong>
                      {selected.host}:{selected.httpPort}
                    </strong>
                  </div>
                  <div className={styles.row}>
                    <span>Trạng thái</span>
                    <strong>{selected.online ? 'Online' : 'Offline'}</strong>
                  </div>
                  <div className={styles.row}>
                    <span>Giới hạn tốc độ</span>
                    <strong>{selected.speedLimitKmh} km/h</strong>
                  </div>
                </>
              )}
              {inspectTab === 'count' && (
                <>
                  <div className={styles.row}>
                    <span>Tổng số phương tiện (live)</span>
                    <strong>{fmtNum(selected.countToday)}</strong>
                  </div>
                  {(Object.keys(selected.countByType) as Array<keyof typeof selected.countByType>).map(
                    (k) => (
                      <div key={k} className={styles.row}>
                        <span>{k}</span>
                        <strong>{fmtNum(selected.countByType[k])}</strong>
                      </div>
                    ),
                  )}
                  <p className={styles.meta}>Mock tick 3s · P2 gắn event camera thật</p>
                </>
              )}
              {inspectTab === 'speed' && (
                <table className={styles.table}>
                  <thead>
                    <tr>
                      <th>Giờ</th>
                      <th>BKS</th>
                      <th>Loại</th>
                      <th>Tốc độ</th>
                      <th>GT</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selected.events.length === 0 ? (
                      <tr>
                        <td colSpan={5} className={styles.meta}>
                          Chưa có xe vượt tốc độ
                        </td>
                      </tr>
                    ) : (
                      selected.events.map((ev) => (
                        <tr key={ev.id}>
                          <td>{ev.at}</td>
                          <td>{ev.plate}</td>
                          <td>{ev.vehicleType}</td>
                          <td>
                            <strong>{ev.speedKmh}</strong> km/h
                          </td>
                          <td>{ev.limitKmh}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              )}
            </div>
          </aside>
        </>
      )}

      {fsCam && (
        <div className={styles.fs} role="dialog" aria-label="Toàn màn hình camera">
          <div className={styles.fsBar}>
            <strong>
              {fsCam.code} · {fsCam.intersection}
            </strong>
            <button type="button" className={live.btn} onClick={() => setFsId(null)}>
              Đóng
            </button>
          </div>
          <div className={styles.fsLive}>
            {fsCam.online
              ? `LIVE mock · ${fmtNum(fsCam.countToday)} xe · ${fsCam.events.length} vượt tốc`
              : 'Mất tín hiệu'}
          </div>
        </div>
      )}
    </div>
  );
};

export default GisCameraMapPage;
