import { useEffect } from 'react';
import { setNavTitle } from '@linm-soft-org/linm-web-common-components';
import { isStandalone } from '../dev/isStandalone';

/** Form / sub-route title override for shell topbar (ROUTER-P1-08). */
export function useShellPageTitle(title: string): void {
  useEffect(() => {
    if (isStandalone) return;
    setNavTitle(title);
    return () => setNavTitle('');
  }, [title]);
}
